12	/// A single node in the [`StoreSubscriptions`] tree. Each path is a specific view into the store
13	/// and can be subscribed to and marked dirty separately. If the whole store is read or written to, all
14	/// nodes in the subtree are subscribed to or marked as dirty.
15	#[derive(Clone, Default)]
16	pub(crate) struct SelectorNode {
17	    subscribers: HashSet<ReactiveContext>,
18	    root: HashMap<PathKey, SelectorNode>,
19	}
20	
21	impl SelectorNode {
22	    /// Get an existing selector node by its path.
23	    fn get(&self, path: &[PathKey]) -> Option<&SelectorNode> {
24	        let [first, rest @ ..] = path else {
25	            return Some(self);
26	        };
27	        self.root.get(first).and_then(|child| child.get(rest))
28	    }
29	
30	    /// Get an existing selector node by its path mutably.
31	    fn get_mut(&mut self, path: &[PathKey]) -> Option<&mut SelectorNode> {
32	        let [first, rest @ ..] = path else {
33	            return Some(self);
34	        };
35	        self.root
36	            .get_mut(first)
37	            .and_then(|child| child.get_mut(rest))
38	    }
39	
40	    /// Get a selector mutably or create one if it doesn't exist. This is used when subscribing to
41	    /// a path that may not exist yet.
42	    fn get_mut_or_default(&mut self, path: &[PathKey]) -> &mut SelectorNode {
43	        let [first, rest @ ..] = path else {
44	            return self;
45	        };
46	        self.root
47	            .entry(*first)
48	            .or_default()
49	            .get_mut_or_default(rest)
50	    }
51	
52	    /// Get the path to each node under this node
53	    ///
54	    /// This is used to mark nodes dirty recursively when a Store is written to.
55	    fn paths_under(&self, current_path: &[PathKey], paths: &mut Vec<Box<[PathKey]>>) {
56	        paths.push(current_path.into());
57	        for (i, child) in self.root.iter() {
58	            let mut child_path: Vec<PathKey> = current_path.into();
59	            child_path.push(*i);
60	            child.paths_under(&child_path, paths);
61	        }
62	    }
63	
64	    /// Get paths to only children before a certain index.
65	    ///
66	    /// This is used when inserting a new item into a list.
67	    /// Items after the index that is inserted need to be marked dirty because the value that index points to may have changed.
68	    fn paths_at_and_after_index(
69	        &self,
70	        path: &[PathKey],
71	        index: usize,
72	        paths: &mut Vec<Box<[PathKey]>>,
73	    ) {
74	        let Some(node) = self.get(path) else {
75	            return;
76	        };
77	
78	        // Mark the nodes before the index as dirty
79	        for (i, child) in node.root.iter() {
80	            if *i as usize >= index {
81	                let mut child_path: Vec<PathKey> = path.into();
82	                child_path.push(*i);
83	                child.paths_under(&child_path, paths);
84	            }
85	        }
86	    }
87	
88	    /// Remove a path from the subscription tree
89	    fn remove(&mut self, path: &[PathKey]) {
90	        let [first, rest @ ..] = path else {
91	            return;
92	        };
93	        if let Some(node) = self.root.get_mut(first) {
94	            if rest.is_empty() {
95	                self.root.remove(first);
96	            } else {
97	                node.remove(rest);
98	            }
99	        }
100	    }
101	}
