50	        &self,
51	    ) -> impl ExactSizeIterator<Item = Store<I, IndexWrite<usize, Lens>>>
52	           + DoubleEndedIterator
53	           + FusedIterator
54	           + '_
55	    where
56	        Lens: Clone,
57	    {
58	        (0..self.len()).map(move |i| self.clone().index(i))
59	    }
60	
