    /// Writing to a nested path should notify the subscribers at and below that path as well as the
    /// deep subscribers of every ancestor, and it should notify each of them exactly once.
    #[test]
    fn mark_dirty_marks_descendants_without_remarking_ancestors() {
        // A minimal virtual dom gives us a runtime and root scope to allocate reactive state in.
        let mut dom = VirtualDom::new(|| VNode::empty());
        dom.rebuild_in_place();
        dom.in_scope(ScopeId::ROOT, || {
            let subscriptions = StoreSubscriptions::new();

            // Each reactive context counts how many times it is marked dirty so we can assert there
            // are no double-notifications.
            fn counting_context() -> (ReactiveContext, Arc<AtomicUsize>) {
                let count = Arc::new(AtomicUsize::new(0));
                let count_clone = count.clone();
                let rc = ReactiveContext::new_with_callback(
                    move || {
                        count_clone.fetch_add(1, Ordering::SeqCst);
                    },
                    current_scope_id(),
                    std::panic::Location::caller(),
                );
                (rc, count)
            }

            let (root, root_count) = counting_context();
            let (child, child_count) = counting_context();
            let (leaf, leaf_count) = counting_context();

            // A deep subscriber at the root path, a deep subscriber at [1, 2], and a shallow
            // subscriber at [1, 2, 3].
            root.subscribe(subscriptions.deep_subscribers(&[]));
            child.subscribe(subscriptions.deep_subscribers(&[1, 2]));
            leaf.subscribe(subscriptions.shallow_subscribers(&[1, 2, 3]));

            // Writing to [1] should notify:
            // - the root deep subscriber (an ancestor of [1])
            // - the deep subscriber at [1, 2] (a descendant of [1])
            // - the shallow subscriber at [1, 2, 3] (a descendant of [1])
            subscriptions.mark_dirty(&[1]);

            assert_eq!(
                root_count.load(Ordering::SeqCst),
                1,
                "the root deep subscriber should be notified exactly once"
            );
            assert_eq!(
                child_count.load(Ordering::SeqCst),
                1,
                "the deep subscriber at [1, 2] should be notified exactly once"
            );
            assert_eq!(
                leaf_count.load(Ordering::SeqCst),
                1,
                "the shallow subscriber at [1, 2, 3] should be notified exactly once"
            );
        });
    }
