fn counting_context() -> (ReactiveContext, Arc<AtomicUsize>) {
    let count = Arc::new(AtomicUsize::new(0));
    let count_clone = count.clone();
    let rc = ReactiveContext::new_with_callback(
        move || {
            count_clone.fetch_add(1, Ordering::SeqCst);
        },
        current_scope_id(),
        std::panic::Location::caller(),
    );
    (rc, count)
}

fn main() {
    let mut dom = VirtualDom::new(|| VNode::empty());
    dom.rebuild_in_place();
    dom.in_scope(ScopeId::ROOT, || {
        // ---- 1: parent deep subscription notified on nested child write ----
        {
            let store = Store::new(Outer::default());
            let (parent, parent_count) = counting_context();
            parent.run_in(|| {
                let _ = store.cloned(); // read whole value -> deep subscribe at root
            });
            store.inner().a().set(5);
            assert_eq!(parent_count.load(Ordering::SeqCst), 1, "parent deep sub on nested write");
        }

        // ---- 2: sibling isolation across nesting ----
        {
            let store = Store::new(Outer::default());
            let (sib, sib_count) = counting_context();
            sib.run_in(|| {
                let _ = store.inner().b().cloned();
            });
            store.inner().a().set(9); // write sibling field
            store.other().set(3); // write unrelated field
            assert_eq!(sib_count.load(Ordering::SeqCst), 0, "sibling must not rerender");
        }

        // ---- 3: grandparent notified on grandchild write (arbitrary depth) ----
        {
            let store = Store::new(Outer::default());
            let (gp, gp_count) = counting_context();
            gp.run_in(|| {
                let _ = store.inner().cloned(); // deep sub at inner
            });
            store.inner().a().set(1);
            assert_eq!(gp_count.load(Ordering::SeqCst), 1, "grandparent deep sub");
        }

        // ---- 4: vec index write shallow: whole-vec (len) not notified, index notified ----
        {
            let store = Store::new(Outer {
                list: vec![1, 2, 3],
                ..Default::default()
            });
            let (whole, whole_count) = counting_context();
            let (idx, idx_count) = counting_context();
            whole.run_in(|| {
                let _ = store.list().len(); // shallow subscribe to vec
            });
            idx.run_in(|| {
                let _ = store.list().index(1).cloned(); // deep subscribe to element 1
            });
            store.list().index(1).set(20);
            assert_eq!(whole_count.load(Ordering::SeqCst), 0, "whole vec not notified on index write");
            assert_eq!(idx_count.load(Ordering::SeqCst), 1, "index notified on index write");
        }

        // ---- 5: push notifies whole-vec (len) but not existing index ----
        {
            let store = Store::new(Outer {
                list: vec![1, 2, 3],
                ..Default::default()
            });
            let (whole, whole_count) = counting_context();
            let (idx, idx_count) = counting_context();
            whole.run_in(|| {
                let _ = store.list().len();
            });
            idx.run_in(|| {
                let _ = store.list().index(0).cloned();
            });
            store.list().push(4);
            assert_eq!(whole_count.load(Ordering::SeqCst), 1, "whole vec notified on push");
            assert_eq!(idx_count.load(Ordering::SeqCst), 0, "existing index not notified on push");
        }

        // ---- 6: nested vec push notifies parent struct but not sibling ----
        {
            let store = Store::new(Outer {
                list: vec![1, 2, 3],
                ..Default::default()
            });
            let (parent, parent_count) = counting_context();
            let (sib, sib_count) = counting_context();
            parent.run_in(|| {
                let _ = store.cloned(); // deep sub whole struct
            });
            sib.run_in(|| {
                let _ = store.other().cloned(); // sibling field
            });
            store.list().push(4);
            assert_eq!(parent_count.load(Ordering::SeqCst), 1, "parent struct notified on nested push");
            assert_eq!(sib_count.load(Ordering::SeqCst), 0, "sibling field not notified on nested push");
        }
    });

    println!("ALL SCRATCH CHECKS PASSED");
}
